export type DeadrollCharacterPluginRequirements = ClientWithRpc<
  GetAccountInfoApi & GetMultipleAccountsApi
> &
  ClientWithPayer &
  ClientWithTransactionPlanning &
  ClientWithTransactionSending;

export function deadrollCharacterProgram() {
  return <T extends DeadrollCharacterPluginRequirements>(
    client: T,
  ): ExtendedClient<T, { deadrollCharacter: DeadrollCharacterPlugin }> => {
    return extendClient(client, {
      deadrollCharacter: {
        accounts: {
          bag: addSelfFetchFunctions(client, getBagCodec()),
          character: addSelfFetchFunctions(client, getCharacterCodec()),
          playerProfile: addSelfFetchFunctions(client, getPlayerProfileCodec()),
          skillExtras: addSelfFetchFunctions(client, getSkillExtrasCodec()),
          skillSet: addSelfFetchFunctions(client, getSkillSetCodec()),
        },
        instructions: {
          createCharacter: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getCreateCharacterInstructionAsync(input),
            ),
          createProfile: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getCreateProfileInstructionAsync(input),
            ),
          equip: (input) =>
            addSelfPlanAndSendFunctions(client, getEquipInstruction(input)),
          freezeTombstone: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getFreezeTombstoneInstruction({
                ...input,
                payer: input.payer ?? client.payer,
              }),
            ),
          grantRewards: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getGrantRewardsInstructionAsync(input),
            ),
          lockForSession: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getLockForSessionInstructionAsync(input),
            ),
          markDead: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getMarkDeadInstructionAsync(input),
            ),
          setSkillDescription: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getSetSkillDescriptionInstructionAsync(input),
            ),
          spendStatPoints: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getSpendStatPointsInstruction(input),
            ),
          unequip: (input) =>
            addSelfPlanAndSendFunctions(client, getUnequipInstruction(input)),
          unlock: (input) =>
            addSelfPlanAndSendFunctions(client, getUnlockInstruction(input)),
        },
        pdas: {
          profile: findProfilePda,
          skillSet: findSkillSetPda,
          bag: findBagPda,
          skillExtras: findSkillExtrasPda,
        },
        identifyAccount: identifyDeadrollCharacterAccount,
        identifyInstruction: identifyDeadrollCharacterInstruction,
        parseInstruction: parseDeadrollCharacterInstruction,
      } as DeadrollCharacterPlugin,
    });
  };
}

